options.script:
let x = data.series[0].fields.find(f => f.name === "year_start").values;
let y = data.series[0].fields.find(f => f.name === "cf_inst").values;
let nom_installation = data.series[0].fields.find(f => f.name === "nom_installation").values;
let nb_groupes = data.series[0].fields.find(f => f.name === "nb_groupes").values;
let nb_installations = data.series[0].fields.find(f => f.name === "nb_installations").values;
let energie_annuelle_glissante_injectee = data.series[0].fields.find(f => f.name === "energie_annuelle_glissante_injectee").values;
let puis_max_installee = data.series[0].fields.find(f => f.name === "puis_max_installee").values;
let puis_max_rac = data.series[0].fields.find(f => f.name === "puis_max_rac").values;
let commune = data.series[0].fields.find(f => f.name === "commune").values;
let departement = data.series[0].fields.find(f => f.name === "departement").values;
let region = data.series[0].fields.find(f => f.name === "region").values;
let regime = data.series[0].fields.find(f => f.name === "regime").values;
let date_mise_en_service = data.series[0].fields.find(f => f.name === "date_mise_en_service").values;
let year_prod = data.series[0].fields.find(f => f.name === "year_prod").values;

let customdata = nom_installation.map((n,i) => [
  n, 
  nb_groupes[i],
  nb_installations[i],
  energie_annuelle_glissante_injectee[i],
  puis_max_installee[i],
  puis_max_rac[i],
  commune[i],
  departement[i],
  region[i],
  regime[i],
  date_mise_en_service[i],
  year_prod[i]
]);

let trace1 = { 
  type: 'violin',
  x,
  y,
  customdata,
  hovertemplate: 
`Nom: %{customdata[0]}
<br>Facteur de charge: %{y:.3f}
<br>Nb groupes: %{customdata[1]}
<br>Nb installations: %{customdata[2]}
<br>Energie annuelle glissante injectée: %{customdata[3]} kWh
<br>P. max installée: %{customdata[4]} kW
<br>P. max rac: %{customdata[5]} kW
<br>Commune: %{customdata[6]}
<br>Département: %{customdata[7]}
<br>Région: %{customdata[8]}
<br>Régime: %{customdata[9]}
<br>Date mise en service: %{customdata[10]}
<br>Année d'installation: %{x}
<br>Année de production: %{customdata[11]}
<extra></extra>`,
  pointpos: 0,
  points: "all",
  fillcolor: "#FF000020",
  marker: {
    size: 3,
    color: '#4554ff',
    outliercolor: 'blue'
  },
  meanline: {
    visible: true,
  }
};

return { data: [trace1] };

options.styles:
a:link {
  color: #0000FF;
}

a:visited {
  color: #800080;
}

a:active {
  color: #FF0000;
}
